int kvm_dev_ioctl_create_device(struct kvm *kvm, struct kvm_create_device *cd) {
    int r = -EINVAL;
    struct kvm_device_ops *ops = NULL;
    struct kvm_device *dev = NULL;
    int fd = -1;

    if (!kvm || !cd)
        return -EINVAL;

    ops = kvm_find_device_ops(cd->type);
    if (!ops)
        return -ENODEV;

    if (cd->flags & KVM_CREATE_DEVICE_TEST)
        return 0;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->kvm = kvm;
    dev->ops = ops;

    mutex_lock(&kvm->lock);
    r = ops->create(dev, cd->flags);
    if (r < 0)
        goto unlock;

    list_add(&dev->list, &kvm->devices);

    if (ops->init) {
        r = ops->init(dev);
        if (r < 0)
            goto err;
    }

    fd = kvm_ioctl_create_device_get_fd(dev);
    if (fd < 0) {
        r = fd;
        goto err;
    }

    cd->fd = fd;
    mutex_unlock(&kvm->lock);
    return 0;

err:
    list_del(&dev->list);
    if (ops->destroy)
        ops->destroy(dev);
unlock:
    mutex_unlock(&kvm->lock);
    kfree(dev);
    return r;
}
